namespace qqworld_collector\module\artificial_intelligence; if (!defined('ABSPATH')) { exit; } class QQWorld_AI_API_Handler { private $provider; private $model; private $api_key; private $api_url; private $supports_tools; public function __construct($provider, $model, $config) { $this->provider = $provider; $this->model = $model; $this->api_key = isset($config['apikey']) ? $config['apikey'] : ''; $this->api_url = isset($config['api']) ? rtrim($config['api'], '/') : ''; $this->supports_tools = isset($config['models']) ? $this->model_supports_tools($model, $config['models']) : false; } private function model_supports_tools($model_name, $models) { foreach ($models as $model) { if ($model['name'] === $model_name) { return isset($model['tools']) && $model['tools'] === true; } } return false; } public function supports_tools() { return $this->supports_tools; } public function get_model_context($config) { foreach ($config['models'] as $model) { if ($model['name'] === $this->model) { return isset($model['ctx']) ? $model['ctx'] : 4096; } } return 4096; } public function chat($messages, $tools = null, $stream = true, $temperature = null) { $headers = array( 'Content-Type' => 'application/json', 'Authorization' => 'Bearer ' . $this->api_key, ); $payload = array( 'model' => $this->model, 'messages' => $messages, 'stream' => $stream, ); if ($temperature !== null) { $payload['temperature'] = $temperature; } if ($tools && $this->supports_tools) { $payload['tools'] = $tools; $payload['tool_choice'] = 'auto'; } $response = $this->make_request($payload, $headers); return $response; } public function chat_stream($messages, $tools = null) { $headers = array( 'Content-Type: application/json', 'Authorization: Bearer ' . $this->api_key, ); $payload = array( 'model' => $this->model, 'messages' => $messages, 'stream' => true, ); if ($tools && $this->supports_tools) { $payload['tools'] = $tools; $payload['tool_choice'] = 'auto'; } return $this->make_stream_request($payload, $headers); } priv