array( 'error' => true, 'message' => '响应解析失败', 'debug' => array( 'json_error' => json_last_error_msg(), 'body_preview' => substr($body, 0, 200), ), ); } return $this->parse_response($data); } private function get_error_summary($body) { if (strlen($body) > 500) { return substr($body, 0, 500) . '...'; } return $body; } private function parse_response($data) { if (isset($data['error'])) { return array( 'error' => true, 'message' => isset($data['error']['message']) ? $data['error']['message'] : 'Unknown error', ); } if (!isset($data['choices']) || empty($data['choices'])) { return array( 'error' => true, 'message' => 'API返回数据格式错误', ); } $choice = $data['choices'][0]; $message = $choice['message']; $result = array( 'error' => false, 'content' => isset($message['content']) ? $message['content'] : '', 'role' => isset($message['role']) ? $message['role'] : 'assistant', ); if (isset($message['tool_calls']) && !empty($message['tool_calls'])) { $result['tool_calls'] = array(); foreach ($message['tool_calls'] as $tool_call) { $result['tool_calls'][] = array( 'id' => isset($tool_call['id']) ? $tool_call['id'] : '', 'name' => isset($tool_call['function']['name']) ? $tool_call['function']['name'] : '', 'arguments' => isset($tool_call['function']['arguments']) ? $tool_call['function']['arguments'] : '{}', ); } } if (isset($data['usage'])) { $result['usage'] = $data['usage']; } if (isset($choice['finish_reason'])) { $result['finish_reason'] = $choice['finish_reason']; } return $result; } public function get_provider_name() { return $this->provider; } public function get_model_name() { return $this->model; } public function get_api_url() { return $this->api_url; } public function get_api_key() { return $this->api_key; } } 